            return;
        }
    }
    if (options.setup) {
        await runSetupFlow(options.key, options.global);
        return;
    }
    if (options.listDocs) {
        listDocs();
        return;
    }
    if (options.clean) {
        cleanDocs();
        return;
    }
    const exportOnly = options.exportPdf &&
        !options.scan &&
        !options.ci &&
        !options.setup &&
        !options.listDocs &&
        !options.clean &&
        !options.update &&
        !options.showConfig &&
        !options.key;
    if (exportOnly) {
        exportDocsAsPdf();
        return;
    }
    const showConfigOnly = options.showConfig &&
        !options.scan &&
        !options.ci &&
        !options.setup &&
        !options.listDocs &&
        !options.clean &&
        !options.update &&
        !options.exportPdf &&
