import fs from 'fs';

import { resolveGlobalConfigDir, resolveGlobalConfigPath, resolveLocalEnvPath } from './paths.js';

const ensureDir = (dirPath) => {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true, mode: 0o700 });
  }
};

const ENV_KEY_PATTERN = /^\s*(export\s+)?OPENAI_API_KEY\s*=(.*)$/;

const isCommentedOutLine = (line) => /^\s*#/.test(line);

const parseEnvValue = (rawValue) => {
  const trimmed = rawValue.trim();
  if (!trimmed) return '';
  const quoteChar = trimmed[0];
  if (quoteChar === '"' || quoteChar === "'") {
    const closingIndex = trimmed.indexOf(quoteChar, 1);
    if (closingIndex === -1) return trimmed.slice(1);
    return trimmed.slice(1, closingIndex);
  }
  const hashIndex = trimmed.indexOf('#');
  const withoutComment = hashIndex === -1 ? trimmed : trimmed.slice(0, hashIndex);
  return withoutComment.trim();
};

const findEnvKeyLines = (lines) => {
  const matches = [];
  lines.forEach((line, index) => {
    if (isCommentedOutLine(line)) return;
    const match = line.match(ENV_KEY_PATTERN);
    if (match) {
      matches.push({ index, hasExport: Boolean(match[1]), rawValue: match[2] });
    }
  });
  return matches;
};

const readEnvLines = (envPath) => {
  if (!fs.existsSync(envPath)) {
    return { lines: [], trailingNewline: true };
  }
  const content = fs.readFileSync(envPath, 'utf8');
  if (content === '') {
    return { lines: [], trailingNewline: true };
  }
  const trailingNewline = content.endsWith('\n');
  const body = trailingNewline ? content.slice(0, -1) : content;
  return { lines: body.split('\n'), trailingNewline };
};

export const hasLocalApiKey = (cwd = process.cwd()) => Boolean(getLocalApiKey(cwd));

export const getLocalApiKey = (cwd = process.cwd()) => {
  const envPath = resolveLocalEnvPath(cwd);
  const { lines } = readEnvLines(envPath);
  const matches = findEnvKeyLines(lines);
  if (!matches.length) return null;
  const value = parseEnvValue(matches[matches.length - 1].rawValue);
  return value ? value : null;
};

export const setLocalApiKey = (key, cwd = process.cwd()) => {
  if (!key) throw new Error('API key is required');
  const envPath = resolveLocalEnvPath(cwd);
  const { lines, trailingNewline } = readEnvLines(envPath);
  const matches = findEnvKeyLines(lines);
  if (matches.length) {
    const target = matches[matches.length - 1];
    const prefix = target.hasExport ? 'export ' : '';
    lines[target.index] = `${prefix}OPENAI_API_KEY=${key}`;
  } else {
    lines.push(`OPENAI_API_KEY=${key}`);
  }
  const content = lines.join('\n') + (trailingNewline ? '\n' : '');
  fs.writeFileSync(envPath, content, { encoding: 'utf8', mode: 0o600 });
  return envPath;
};

export const hasGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) =>
  Boolean(getGlobalApiKey(homeDir));

export const getGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) => {
  const configPath = resolveGlobalConfigPath(homeDir);
  if (!fs.existsSync(configPath)) return null;
  const content = fs.readFileSync(configPath, 'utf8');
  try {
    const parsed = JSON.parse(content);
    const value = parsed?.OPENAI_API_KEY;
    return typeof value === 'string' && value.trim() ? value.trim() : null;
  } catch (error) {
    return null;
  }
};

export const setGlobalApiKey = (key, homeDir = process.env.HOME || process.env.USERPROFILE) => {
  if (!key) throw new Error('API key is required');
  const configDir = resolveGlobalConfigDir(homeDir);
  ensureDir(configDir);
  const configPath = resolveGlobalConfigPath(homeDir);
  let parsed = {};
  if (fs.existsSync(configPath)) {
    const content = fs.readFileSync(configPath, 'utf8');
    try {
      parsed = content.trim() ? JSON.parse(content) : {};
    } catch (error) {
      throw new Error(`Global config at ${configPath} is not valid JSON: ${error.message}`);
    }
  }
  const payload = JSON.stringify({ ...parsed, OPENAI_API_KEY: key }, null, 2);
  fs.writeFileSync(configPath, payload, { encoding: 'utf8', mode: 0o600 });
  return configPath;
};

